    float = true,
})

-- Popups opened from waybar: float under the bar at the top right,
-- and close as soon as focus moves to another window
-- class -> where the popup opens (just under the pill that opened it)
local popupClasses = {
    -- (waypaper used to be here; the wallpaper picker is now waytrogen, see popupTitles)
}
for class, move in pairs(popupClasses) do
    hl.window_rule({
        name  = "popup-" .. class,
        match = { class = "^" .. class:gsub("%.", "\\.") .. "$" },

        float       = true,
        move        = move,
        border_size = 1,
        no_shadow   = true,
    })
end
-- same, for apps that set no class (matched by exact title instead)
-- waytrogen (iced) leaves app_id empty, so its title is the only handle
local popupTitles = {
    ["Waytrogen - Iced"]       = { move = "monitor_w*0.5-window_w*0.5 48",  -- island, top center
                                   size = "monitor_w*0.5 monitor_h*0.6" },
}
for title, opt in pairs(popupTitles) do
    hl.window_rule({
        name  = "popup-title-" .. title:gsub("%W", ""),
        match = { title = "^" .. title:gsub("([%.%-%+%*%?%(%)%[%]%^%$])", "\\%1") .. "$" },

        float       = true,
        size        = opt.size,
        move        = opt.move,
        border_size = 1,
        no_shadow   = true,
    })
end
hl.on("window.active", function (window)
  if window and (popupClasses[window.class] or popupTitles[window.title]) then
    return
  end
  for class in pairs(popupClasses) do
    for _, popup in ipairs(hl.get_windows({ class = class })) do
      hl.dispatch(hl.dsp.window.close({ window = "address:" .. popup.address }))
    end
  end
  for _, w in ipairs(hl.get_windows({})) do
    if popupTitles[w.title] then
      hl.dispatch(hl.dsp.window.close({ window = "address:" .. w.address }))
    end
  end
end)

-- Miku greeting terminal (~/.local/bin/miku-boot): an ordinary tiled column on the
-- current workspace (full height), 70% wide (widest greeting line = 124 columns,
-- 70% gives ~135)
hl.window_rule({
    name  = "miku-greeter",
    match = { class = "^miku-greeter$" },

    scrolling_width = 0.7,
})

-- Toss Invest web app (~/.local/share/applications/toss-invest.desktop): opens maximized
hl.window_rule({
    name  = "toss-invest",
    match = { class = "^chrome-www\\.tossinvest\\.com__-Default$" },

    maximize = true,
})

-- YouTube web app (~/.local/share/applications/youtube.desktop): opens maximized
hl.window_rule({
    name  = "youtube",
    match = { class = "^chrome-www\\.youtube\\.com__-Default$" },

    maximize = true,
})

-- Keybind cheatsheet (~/.local/bin/hypr-cheatsheet, not started at login; SUPER+/
-- shows/hides it): floating, on every workspace,
-- no focus on open/hover, top right under waybar
hl.window_rule({
    name  = "hypr-cheatsheet",
    match = { class = "^local\\.hypr\\.cheatsheet$" },

    float            = true,
    pin              = true,
    no_initial_focus = true,
    no_follow_mouse  = true,
    no_shadow        = true,
    no_dim           = true,
    border_size      = 0,
    move             = "monitor_w-window_w-16 56",
})

-- Linux command dictionary (~/.local/share/linux-cheatsheet): floats centered;
-- SUPER+I shows/hides it via ~/.local/bin/popup-window
hl.window_rule({
    name  = "linux-cheatsheet",
    match = { class = "^local\\.LinuxCheatsheet$" },

    float     = true,
    size      = "monitor_w*0.8 monitor_h*0.9",
    center    = true,
})


-- GNOME Settings (Wi-Fi / Bluetooth, opened from the control center's 기기 연결
-- via ~/.local/bin/device-settings): floating, centered
hl.window_rule({
    name  = "gnome-settings",
    match = { class = "^org\\.gnome\\.Settings$" },

    float  = true,
    size   = "1000 720",
    center = true,
})

-- clipse (clipboard history, SUPER+SHIFT+V): floating, centered
hl.window_rule({
    name  = "clipse",
    match = { class = "^clipse$" },

    float  = true,
    size   = "720 640",
    center = true,
})
